var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	if str(w.get("window_id", "")) != "movement_phase_start":
		break
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return p != null and not p.has_pending_stratagem_window()

# Tier A: every token's silhouette_category is the category its unit's keywords
# call for, by this scenario's own table (body type first - AIRCRAFT, WALKER,
# MOUNTED, VEHICLE, MONSTER/BEAST(S)/SWARM - then CHARACTER, else infantry).
var n = 0
var seen = {}
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var uid = str(t.get_meta("unit_id"))
	var k = {}
	for x in GameState.get_unit(uid).get("meta", {}).get("keywords", []):
		k[str(x).to_upper()] = true
	var want = "infantry"
	if k.has("AIRCRAFT"):
		want = "aircraft"
	elif k.has("WALKER"):
		want = "walker"
	elif k.has("MOUNTED"):
		want = "mounted"
	elif k.has("VEHICLE"):
		want = "tank"
	elif k.has("MONSTER") or k.has("BEAST") or k.has("BEASTS") or k.has("SWARM"):
		want = "beast"
	elif k.has("CHARACTER"):
		want = "character"
	if str(t.silhouette_category) != want:
		return "%s/%s: silhouette_category '%s', keywords call for '%s'" % [uid, str(t.get_meta("model_id")), str(t.silhouette_category), want]
	seen[want] = true
	n += 1
var cats = seen.keys()
cats.sort()
return "ok %d tokens: %s" % [n, ",".join(cats)]

# Tier A, named units: INFANTRY Boyz / Witchseekers -> infantry, the VEHICLE
# (FLY) Caladius -> tank, dreadnoughts -> walker, the Wazbom -> aircraft, the
# jetbike Shield-Captain -> mounted, Warboss / Shield-Captain -> character, the
# MONSTER Ghazghkull -> beast.
var want = ["U_BATTLEWAGON_G", "U_BOYZ_E", "U_CALADIUS_GRAV-TANK_E", "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H", "U_GHAZGHKULL_THRAKA_A", "U_SHIELD_CAPTAIN_A", "U_SHIELD_CAPTAIN_JETBIKE_A", "U_TELEMON_HEAVY_DREADNOUGHT_I", "U_WARBOSS_B", "U_WAZBOM_BLASTAJET", "U_WITCHSEEKERS_C"]
var got = {}
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if t.has_meta("unit_id") and str(t.get_meta("model_id")) == "m1":
		got[str(t.get_meta("unit_id"))] = str(t.silhouette_category)
var out = []
for uid in want:
	out.append("%s=%s" % [uid.trim_prefix("U_"), got.get(uid, "missing")])
return ", ".join(out)

# Tier A on every token: a Silhouette node whose texture is the category's SVG
# (res://assets/icons/unit_silhouettes/<cat>.svg, imported 256 px). It is
# painted (visible) exactly when the token has no dedicated art and is not a
# tank keeping the generic tank sprite; a painted glyph is opaque, at the
# T15_GLYPH_SCALE size, tinted the base's contrast colour (ring mode: the light
# 0.95 grey on the dark slate base).
var painted = 0
var kept = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var key = "%s/%s" % [str(t.get_meta("unit_id")), str(t.get_meta("model_id"))]
	var s = t.get_node_or_null("Silhouette")
	if s == null:
		return key + ": no Silhouette node"
	if s.texture == null:
		return key + ": Silhouette.texture is null"
	if s.texture.resource_path != "res://assets/icons/unit_silhouettes/%s.svg" % t.silhouette_category:
		return "%s: texture %s is not the %s glyph" % [key, s.texture.resource_path, t.silhouette_category]
	if s.texture.get_width() != 256 or s.texture.get_height() != 256:
		return "%s: texture %s" % [key, str(s.texture.get_size())]
	var keeps_art = t._get_unit_sprite_texture() != null or (t.silhouette_category == "tank" and t._get_tank_body_texture() != null)
	if s.visible == keeps_art:
		return "%s: painted=%s but keeps_art=%s" % [key, str(s.visible), str(keeps_art)]
	if s.visible:
		if s.modulate != Color(0.95, 0.95, 0.95) or absf(s.scale.x - 0.66) > 0.001:
			return "%s: glyph modulate %s scale %s" % [key, s.modulate.to_html(), str(s.scale)]
		painted += 1
	else:
		kept += 1
return "ok painted=%d kept_art=%d" % [painted, kept]

# Tier A: every token's letter counter is its Label child, laid out under the
# base: text = the unit's letter (custom label or auto letter), top below the
# base's lowest point, centred, visible, 13 px bold with an outline, drawn beneath
# the tokens (z_index -1). The model carrying the unit's name plate leaves it
# empty - its plate names the unit under that base.
var letters = 0
var plates = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var key = "%s/%s" % [str(t.get_meta("unit_id")), str(t.get_meta("model_id"))]
	var l = t.get_node_or_null("Label")
	if l == null:
		return key + ": no Label"
	if l.z_index != -1 or not l.visible:
		return "%s: Label z_index %d visible %s" % [key, l.z_index, str(l.visible)]
	if t._t15_name_plate_shown():
		if l.text != "":
			return "%s: carries the name plate but its Label reads '%s'" % [key, l.text]
		plates += 1
		continue
	if l.text != t._get_letter_label() or l.text == "":
		return "%s: Label '%s' != letter '%s'" % [key, l.text, t._get_letter_label()]
	var lowest = -INF
	for p in t._get_shape_polygon(t.model_data.get("rotation", 0.0)):
		lowest = max(lowest, p.y)
	if l.position.y < lowest:
		return "%s: Label top %.1f is above the base bottom %.1f" % [key, l.position.y, lowest]
	if absf(l.position.x + l.size.x / 2.0) > 1.0:
		return "%s: Label not centred (x %.1f w %.1f)" % [key, l.position.x, l.size.x]
	if l.get_theme_font_size("font_size") != 13 or l.get_theme_constant("outline_size") < 2 or not l.get_theme_font("font").resource_path.ends_with("Rajdhani-Bold.ttf"):
		return "%s: Label size=%d outline=%d font=%s" % [key, l.get_theme_font_size("font_size"), l.get_theme_constant("outline_size"), l.get_theme_font("font").resource_path]
	letters += 1
return "ok letters=%d name_plates=%d" % [letters, plates]

# Template match: the glyph on screen is the token's own SVG glyph. Over a
# 16x16 grid on the glyph rect, points where the texture is solid white fill
# (5 texels agree) must be light on screen, solid black (keyline / holes) dark,
# and clear points inside 0.6 r (base interior) not light. A letter counter, an
# empty base or another category's glyph fails it.
var only = ["U_WARBOSS_B/m1", "U_WARBOSS_C/m1"]
var white_min = 0.75
var ratio_min = 0.9
var m = tree.root.get_node("Main")
var shot = tree.root.get_texture().get_image()
var cache = {}
var cats = {}
var bad = []
var worst = 1.0
var best = 0.0
var checked = 0
# Screen footprint of every token drawn after another (its base circle, and
# below the base its letter label / name plate) - a glyph under one is skipped.
var toks = []
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if t.has_meta("unit_id"):
		toks.append(t)
var foot = []
for o in toks:
	var oxf = o.get_global_transform_with_canvas()
	var ob = o.base_shape.get_bounds()
	var orad = max(ob.size.x, ob.size.y) / 2.0 * oxf.get_scale().x
	var oc = oxf.origin
	foot.append([oc, orad, Rect2(oc.x - 100.0 * oxf.get_scale().x, oc.y + orad, 200.0 * oxf.get_scale().x, 50.0 * oxf.get_scale().x)])
for i in range(toks.size()):
	var t = toks[i]
	var key = "%s/%s" % [str(t.get_meta("unit_id")), str(t.get_meta("model_id"))]
	if only.size() > 0 and not only.has(key):
		continue
	var rect = t.t15_silhouette_rect()
	if rect.is_empty() or (only.size() == 0 and not rect["painted"]):
		continue
	var xf = t.get_global_transform_with_canvas()
	var p0 = xf * rect["position"]
	var p1 = xf * (rect["position"] + rect["size"])
	if p0.x < 345 or p0.y < 105 or p1.x > 1515 or p1.y > 1045:
		continue
	var grect = Rect2(p0, p1 - p0)
	var hidden = false
	# (a named token list vouches for its own tokens being in clear view)
	for j in range(i + 1, toks.size() if only.is_empty() else 0):
		var f = foot[j]
		var gc = grect.get_center()
		var near = Vector2(clampf(f[0].x, grect.position.x, grect.end.x), clampf(f[0].y, grect.position.y, grect.end.y))
		if near.distance_to(f[0]) < f[1] or grect.intersects(f[2]):
			hidden = true
			break
	if hidden:
		continue
	var tex = t.get_node("Silhouette").texture
	if not cache.has(tex.resource_path):
		cache[tex.resource_path] = tex.get_image()
	var img = cache[tex.resource_path]
	var w = img.get_width()
	var b = t.base_shape.get_bounds()
	var r = min(b.size.x, b.size.y) / 2.0
	var agree = 0
	var total = 0
	for gy in range(16):
		for gx in range(16):
			var uv = Vector2((gx + 0.5) / 16.0, (gy + 0.5) / 16.0)
			var tx = int(uv.x * w)
			var ty = int(uv.y * w)
			var cls = ""
			var ok_cls = true
			for d in [Vector2i(0, 0), Vector2i(6, 0), Vector2i(-6, 0), Vector2i(0, 6), Vector2i(0, -6)]:
				var c = img.get_pixel(clampi(tx + d.x, 0, w - 1), clampi(ty + d.y, 0, w - 1))
				var k = "clear" if c.a < 0.02 else ("white" if c.a > 0.98 and c.r > 0.9 else ("black" if c.a > 0.98 and c.r < 0.1 else "mixed"))
				if cls == "":
					cls = k
				elif k != cls:
					ok_cls = false
			if not ok_cls or cls == "mixed":
				continue
			var local = rect["position"] + uv * rect["size"]
			if cls == "clear" and local.length() > 0.6 * r:
				continue
			var sp = xf * local
			var px = shot.get_pixel(int(sp.x), int(sp.y))
			var lum = 0.299 * px.r + 0.587 * px.g + 0.114 * px.b
			total += 1
			if (cls == "white" and lum >= white_min) or (cls == "black" and lum <= 0.3) or (cls == "clear" and lum < 0.5):
				agree += 1
	if total < 40:
		bad.append("%s: only %d sample points" % [key, total])
		continue
	var ratio = float(agree) / float(total)
	worst = min(worst, ratio)
	best = max(best, ratio)
	checked += 1
	if ratio < ratio_min:
		bad.append("%s %s %.2f" % [key, t.silhouette_category, ratio])
	else:
		cats[t.silhouette_category] = true
if checked != only.size():
	return "checked %d of %d: %s" % [checked, only.size(), ", ".join(bad)]
if bad.is_empty():
	return "all match"
if bad.size() == checked:
	return "none match" if best < 0.6 else "none match, best %.2f" % best
return "mixed: %s" % ", ".join(bad)

