# The letter labels are drawn: inside each named token's Label rect the frame
# has light text pixels (lum > 0.8) - the board below them is darker.
var want = ["U_BOYZ_E/m20", "U_WITCHSEEKERS_C/m4", "U_CUSTODIAN_GUARD_B/m4"]
var out = []
var shot = tree.root.get_texture().get_image()
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var key = "%s/%s" % [str(t.get_meta("unit_id")), str(t.get_meta("model_id"))]
	if not want.has(key):
		continue
	var l = t.get_node("Label")
	var xf = l.get_global_transform_with_canvas()
	var a = xf * Vector2.ZERO
	var b = xf * l.size
	var light = 0
	for y in range(int(a.y), int(b.y)):
		for x in range(int(a.x), int(b.x)):
			var c = shot.get_pixel(x, y)
			if 0.299 * c.r + 0.587 * c.g + 0.114 * c.b > 0.8:
				light += 1
	out.append("%s:%s" % [key.trim_prefix("U_"), "text" if light >= 8 else "blank(%d)" % light])
